    ...sealDefaults,
    ttl: (config.maxAge || config.idleTimeout || 0) * 1000,
    ...config.seal,
  };
  let unsealed: Partial<Session>;
  try {
    unsealed = (await unseal(sealed, config.password, sealOptions)) as Partial<Session>;
  } catch (error) {
