  // Fail early: the unseal below swallows errors, so an empty list would go unnoticed
  resolvePasswords(config);

  // Prepare an empty session object and store in context
  const session: Session<T> = {
    id: "",
    createdAt: 0,
    data: new EmptyObject(),
