    const newPassword = "new-password-new-password-new-password-1";
    const removedPassword = "removed-password-removed-password-1234";
    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };
    const name = "h3-rot";
    const base = (): SessionConfig => ({ name, password: [newPassword, oldPassword] });
    const sealWith = (pw: string, data: any = { foo: "bar" }, options: any = sealDefaults) =>
      seal({ id: "rot", createdAt: Date.now(), data }, pw, options);
    const cookieValue = (res: Response) =>
      decodeURIComponent(
        res.headers
          .getSetCookie()
          .find((c) => c.startsWith(`${name}=`))!
          .match(/=([^;]+)/)![1],
      );

    function route(config: () => SessionConfig, path = "/rot") {
      t.app.get(path, async (event) => {
        const session = await getSession(event, config());
        return { id: session.id, data: session.data };
      });
    }

    it("seals with the first password only", async () => {
      let ctr = 0;
      const config = { ...base(), generateId: () => `n${++ctr}` };
      t.app.get("/rot-new", async (event) => {
        const session = await useSession(event, config);
        await session.update({ a: 1 });
        return { id: session.id };
      });
      const res = await t.fetch("/rot-new");
      const sealed = cookieValue(res);
      expect(await unseal(sealed, newPassword, sealDefaults)).toMatchObject({ data: { a: 1 } });
      await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow();
    });

    it("accepts sessions sealed with an older password and reseals them", async () => {
      route(base);
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=${await sealWith(oldPassword)}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot", data: { foo: "bar" } });
      expect(res.headers.getSetCookie()).toHaveLength(1);
      const resealed = cookieValue(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({ id: "rot" });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow();
    });

    it("finds an older password further down the list", async () => {
      route(() => ({ name, password: [newPassword, midPassword, oldPassword] }));
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=${await sealWith(oldPassword)}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot", data: { foo: "bar" } });
    });

    it("does not reseal sessions sealed with the first password", async () => {
      route(base);
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=${await sealWith(newPassword)}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot" });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("accepts the session header sealed with an older password without reseal", async () => {
      route(base);
      const res = await t.fetch("/rot", {
        headers: { [`x-${name}-session`]: await sealWith(oldPassword) },
      });
      expect(await res.json()).toMatchObject({ id: "rot" });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("discards sessions sealed with a removed password", async () => {
      let ctr = 0;
      route(() => ({ ...base(), generateId: () => `fresh${++ctr}` }));
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=${await sealWith(removedPassword)}` },
      });
      expect(res.status).toBe(200);
      expect(await res.json()).toEqual({ id: "fresh1", data: {} });
    });

    it("rejects an empty password list", async () => {
      const config: SessionConfig = { name, password: [] };
      const message = /must not be empty/;
      t.app.get("/rot-empty", async (event) => {
        await useSession(event, config);
        return "ok";
      });
      t.app.get("/rot-empty-get", async (event) => {
        await getSession(event, config);
        return "ok";
      });
      for (const path of ["/rot-empty", "/rot-empty-get"]) {
        for (const headers of [{}, { Cookie: `${name}=${await sealWith(oldPassword)}` }]) {
          const res = await t.fetch(path, { headers });
          expect(res.status).toBe(500);
          expect(res.headers.getSetCookie()).toHaveLength(0);
        }
      }
      const event = { req: new Request("http://localhost/"), context: {} } as any;
      const { sealSession, unsealSession } = await import("../src/index.ts");
      await expect(sealSession(event, config)).rejects.toThrow(message);
      await expect(unsealSession(event, config, "x")).rejects.toThrow(message);
      t.errors.length = 0;
    });

    it("unseals legacy sessions sealed with an older password", async () => {
      route(base);
      const legacy = await sealWith(oldPassword, { foo: "legacy" }, legacyOptions);
      const res = await t.fetch("/rot", { headers: { Cookie: `${name}=${legacy}` } });
      expect(await res.json()).toMatchObject({ id: "rot", data: { foo: "legacy" } });
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(await unseal(cookieValue(res), newPassword, sealDefaults)).toMatchObject({
        id: "rot",
      });
    });

    it("rejects legacy sessions with an older password and legacySealFallback: false", async () => {
      let ctr = 0;
      route(() => ({ ...base(), legacySealFallback: false, generateId: () => `f${++ctr}` }));
      const legacy = await sealWith(oldPassword, {}, legacyOptions);
      const res = await t.fetch("/rot", { headers: { Cookie: `${name}=${legacy}` } });
      expect((await res.json()).id).toBe("f1");
    });

    it("enforces maxAge and idleTimeout for older passwords", async () => {
      vi.useFakeTimers({ toFake: ["Date"], now: Date.parse("2030-01-01T00:00:00Z") });
      try {
        for (const limit of ["maxAge", "idleTimeout"] as const) {
          let ctr = 0;
          const path = `/rot-${limit}`;
          route(() => ({ ...base(), [limit]: 60, generateId: () => `${limit}${++ctr}` }), path);
          const sealed = await sealWith(oldPassword);
          const headers = { Cookie: `${name}=${sealed}` };
          expect((await (await t.fetch(path, { headers })).json()).id).toBe("rot");
          vi.setSystemTime(Date.now() + 61_000);
          expect((await (await t.fetch(path, { headers })).json()).id).toBe(`${limit}1`);
          vi.setSystemTime(Date.parse("2030-01-01T00:00:00Z"));
        }
      } finally {
        vi.useRealTimers();
      }
    });

    it("supports custom seal options with an older password", async () => {
      const custom = {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 50 },
        integrity: { ...sealDefaults.integrity, iterations: 50 },
      };
      route(() => ({ ...base(), seal: custom }));
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=${await sealWith(oldPassword, { foo: "bar" }, custom)}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot", data: { foo: "bar" } });
    });

    it("reads chunked cookies sealed with an older password", async () => {
      route(base);
      const token = "x".repeat(5000);
      const sealed = await sealWith(oldPassword, { token });
      const size = 3000;
      const parts = [sealed.slice(0, size), sealed.slice(size)];
      const res = await t.fetch("/rot", {
        headers: { Cookie: `${name}=__chunked__2; ${name}.1=${parts[0]}; ${name}.2=${parts[1]}` },
      });
      expect(await res.json()).toMatchObject({ id: "rot", data: { token } });
    });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });
});

